TEE_Result generate_cryptographic_key(unsigned long obj,
                                      unsigned long key_size,
                                      const struct utee_attribute *usr_params,
                                      unsigned long param_count) {
    TEE_Result result = TEE_ERROR_GENERIC;
    void *session = NULL;
    struct key_attributes *attributes = NULL;
    unsigned long alloc_size;

    session = get_current_session();
    if (!session) {
        return TEE_ERROR_NO_ACCESS;
    }

    result = check_object_state(obj);
    if (result != TEE_SUCCESS) {
        return result;
    }

    result = validate_key_size(key_size, get_object_type(obj));
    if (result != TEE_SUCCESS) {
        return result;
    }

    alloc_size = sizeof(struct key_attributes) * param_count;
    attributes = TEE_Malloc(alloc_size, 0);
    if (!attributes) {
        return TEE_ERROR_OUT_OF_MEMORY;
    }

    result = initialize_attributes(attributes, usr_params, param_count);
    if (result != TEE_SUCCESS) {
        TEE_Free(attributes);
        return result;
    }

    switch (get_object_type(obj)) {
        case OBJECT_TYPE_AES:
            result = generate_aes_key(obj, key_size, attributes, param_count);
            break;
        case OBJECT_TYPE_RSA:
            result = generate_rsa_key(obj, key_size, attributes, param_count);
            break;
        case OBJECT_TYPE_DSA:
            result = generate_dsa_key(obj, key_size, attributes, param_count);
            break;
        default:
            result = TEE_ERROR_NOT_SUPPORTED;
    }

    if (result != TEE_SUCCESS) {
        TEE_Free(attributes);
    }

    return result;
}

TEE_Result generate_key_for_object(unsigned long obj,
                                   unsigned long key_size,
                                   const struct utee_attribute *usr_params,
                                   unsigned long param_count) {
    TEE_Session *session;
    TEE_ObjectInfo obj_info;
    struct utee_attribute *attributes = NULL;
    TEE_Result result = TEE_SUCCESS;
    unsigned long total_params;

    session = TEE_GetCurrentSession();
    if (!session) {
        return TEE_ERROR_BAD_STATE;
    }

    if (TEE_ObjectGetInfo(obj, &obj_info) != TEE_SUCCESS) {
        return TEE_ERROR_BAD_STATE;
    }

    if (key_size < obj_info.minKeySize || key_size > obj_info.maxKeySize) {
        return TEE_ERROR_BAD_PARAMETERS;
    }

    total_params = obj_info.defaultParamCount + param_count;
    attributes = calloc(total_params, sizeof(struct utee_attribute));
    if (!attributes) {
        return TEE_ERROR_OUT_OF_MEMORY;
    }

    if (param_count > 0) {
        if (memcpy_s(attributes + obj_info.defaultParamCount,
                     param_count * sizeof(struct utee_attribute),
                     usr_params,
                     param_count * sizeof(struct utee_attribute))) {
            free(attributes);
            return TEE_ERROR_BAD_PARAMETERS;
        }
    }

    switch (obj_info.type) {
        case TEE_OBJECT_TYPE_AES:
            result = generate_aes_key(obj, key_size, attributes, total_params);
            break;
        case TEE_OBJECT_TYPE_RSA:
            result = generate_rsa_key(obj, key_size, attributes, total_params);
            break;
        case TEE_OBJECT_TYPE_DSA:
            result = generate_dsa_key(obj, key_size, attributes, total_params);
            break;
        default:
            result = TEE_ERROR_NOT_SUPPORTED;
            break;
    }

    if (result != TEE_SUCCESS) {
        free(attributes);
    }

    return result;
}

TEE_Result generate_cryptographic_key(unsigned long obj,
                                      unsigned long key_size,
                                      const struct utee_attribute *usr_params,
                                      unsigned long param_count) {
    TEE_Session *session = TEE_GetCurrentSession();
    TEE_Object *object = TEE_GetObjectByReference(obj);
    struct utee_attribute *attributes = NULL;
    TEE_Result result = TEE_SUCCESS;

    if (!object) {
        return TEE_ERROR_BAD_PARAMETERS;
    }

    if (key_size < object->min_key_size || key_size > object->max_key_size) {
        return TEE_ERROR_BAD_PARAMETERS;
    }

    attributes = malloc(param_count * sizeof(struct utee_attribute));
    if (!attributes) {
        return TEE_ERROR_OUT_OF_MEMORY;
    }

    memcpy(attributes, usr_params, param_count * sizeof(struct utee_attribute));

    if (object->type == TEE_TYPE_AES) {
        result = generate_aes_key(object, key_size, attributes, param_count);
    } else if (object->type == TEE_TYPE_RSA) {
        result = generate_rsa_key(object, key_size, attributes, param_count);
    } else if (object->type == TEE_TYPE_DSA) {
        result = generate_dsa_key(object, key_size, attributes, param_count);
    } else {
        result = TEE_ERROR_NOT_SUPPORTED;
    }

    if (result != TEE_SUCCESS) {
        free(attributes);
        return result;
    }

    object->key = attributes;
    object->key_size = key_size;
    object->key_count = param_count;

    return TEE_SUCCESS;
}

TEE_Result generate_cryptographic_key(
    unsigned long obj,
    unsigned long key_size,
    const struct utee_attribute* usr_params,
    unsigned long param_count)
{
    TEE_Session* session = TEE_GetCurrentSession();
    if (!session)
        return TEE_ERROR_BAD_STATE;

    TEE_Object* target_obj = TEE_FindObjectById(obj);
    if (!target_obj || !TEE_ObjectIsInitialized(target_obj))
        return TEE_ERROR_BAD_STATE;

    if (key_size < TEE_KEY_SIZE_MIN || key_size > TEE_KEY_SIZE_MAX) {
        return TEE_ERROR_BAD_PARAMETERS;
    }

    struct utee_attribute* all_attrs = NULL;
    unsigned long attr_count = param_count;
    all_attrs = malloc(attr_count * sizeof(struct utee_attribute));
    if (!all_attrs)
        return TEE_ERROR_OUT_OF_MEMORY;

    for (unsigned long i = 0; i < param_count; ++i) {
        all_attrs[i] = usr_params[i];
    }

    TEE_Result result = TEE_ERROR_GENERIC;

    if (TEE_ObjectGetType(target_obj) == TEE_TYPE_AES) {
        result = TEE_GenerateAESKey(target_obj, key_size, all_attrs, attr_count);
    } else if (TEE_ObjectGetType(target_obj) == TEE_TYPE_RSA) {
        result = TEE_GenerateRSAKey(target_obj, key_size, all_attrs, attr_count);
    } else if (TEE_ObjectGetType(target_obj) == TEE_TYPE_DSA) {
        result = TEE_GenerateDSAKey(target_obj, key_size, all_attrs, attr_count);
    } else {
        result = TEE_ERROR_NOT_SUPPORTED;
    }

    free(all_attrs);
    return result;
}

#include <stdlib.h>
#include <string.h>
#include <tee_api.h>

TEE_Result generate_cryptographic_key(
    unsigned long obj,
    unsigned long key_size,
    const struct utee_attribute* usr_params,
    unsigned long param_count)
{
    TEE_Session* session = TEE_GetCurrentSession();
    if (!session) {
        return TEE_ERROR_BAD_STATE;
    }

    // Assume the object is a TEE object and we can check its type
    TEE_ObjectType objectType;
    TEE_Result result = TEE_GetObjectInfo(obj, &objectType, NULL);
    if (result != TEE_SUCCESS) {
        return result;
    }

    // Validate key size against object type constraints
    if ((objectType == TEE_TYPE_AES && key_size != 128 && key_size != 192 && key_size != 256) ||
        (objectType == TEE_TYPE_RSA && key_size < 1024) ||
        (objectType == TEE_TYPE_DSA && key_size < 512)) {
        return TEE_ERROR_BAD_PARAMETERS;
    }

    // Allocate memory for attributes
    struct utee_attribute* attributes = malloc(param_count * sizeof(struct utee_attribute));
    if (!attributes) {
        return TEE_ERROR_OUT_OF_MEMORY;
    }

    memcpy(attributes, usr_params, param_count * sizeof(struct utee_attribute));

    // Generate key based on object type
    if (objectType == TEE_TYPE_AES) {
        result = TEE_GenerateAESKey(obj, key_size, attributes, param_count);
    } else if (objectType == TEE_TYPE_RSA) {
        result = TEE_GenerateRSAKey(obj, key_size, attributes, param_count);
    } else if (objectType == TEE_TYPE_DSA) {
        result = TEE_GenerateDSAKey(obj, key_size, attributes, param_count);
    } else {
        result = TEE_ERROR_NOT_SUPPORTED;
    }

    free(attributes);
    return result;
}
